-- POPForge independent commerce schema (PostgreSQL/Supabase baseline)
create extension if not exists pgcrypto;
create type order_status as enum ('draft','pending_payment','paid','in_production','quality_check','ready_to_ship','shipped','delivered','cancelled','refunded');
create type production_status as enum ('queued','preparing','printing','post_processing','quality_check','completed','failed');
create table customers (id uuid primary key default gen_random_uuid(), email text unique not null, name text not null, phone text, created_at timestamptz not null default now());
create table products (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text, category text not null, active boolean not null default true, customizable boolean not null default false, created_at timestamptz not null default now());
create table product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, sku text unique not null, color text, material text, size text, price_cents integer not null check(price_cents >= 0), stock integer not null default 0, weight_grams integer);
create table orders (id uuid primary key default gen_random_uuid(), order_number bigint generated always as identity unique, customer_id uuid references customers(id), status order_status not null default 'draft', subtotal_cents integer not null default 0, shipping_cents integer not null default 0, total_cents integer not null default 0, stripe_payment_intent_id text unique, tracking_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, variant_id uuid references product_variants(id), product_name text not null, sku text, quantity integer not null check(quantity > 0), unit_price_cents integer not null, customization jsonb not null default '{}'::jsonb);
create table production_jobs (id uuid primary key default gen_random_uuid(), order_item_id uuid not null references order_items(id), status production_status not null default 'queued', printer_name text, material text, color text, estimated_minutes integer, actual_minutes integer, grams_used numeric(10,2), notes text, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table inventory_movements (id uuid primary key default gen_random_uuid(), material text not null, color text, grams numeric(10,2) not null, reason text not null, production_job_id uuid references production_jobs(id), created_at timestamptz not null default now());
create index orders_customer_idx on orders(customer_id, created_at desc);
create index jobs_status_idx on production_jobs(status, created_at);
